import { definePluginEntry } from "openclaw/plugin-sdk/plugin-entry";
const patterns=[["search",/\b(search|research|find current|look up|web)\b/i],["data_enrichment",/\b(enrich|company data|person data|contact data)\b/i],["inference",/\b(inference|classify|extract|summari[sz]e)\b/i],["intelligence",/\b(intelligence|verdict|risk analysis|decision support)\b/i]];
function capability(prompt){if(!prompt||typeof prompt!=="string"||/\b(use|via|through)\s+[A-Z][A-Za-z0-9._-]+/.test(prompt))return null;return patterns.find(([,p])=>p.test(prompt))?.[0]??null}
export default definePluginEntry({id:"phion-pre-resolution",name:"PHION Pre-Resolution",description:"Optional advisory external capability pre-resolution",register(api){api.on("before_prompt_build",async(event,ctx)=>{const config=api.config?.plugins?.entries?.["phion-pre-resolution"]?.config??{};if(config.enabled===false)return;const cap=capability(event?.prompt);if(!cap)return;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),Number(config.timeoutMs??1500));try{const response=await fetch("https://phion.systems/v1/resolve",{method:"POST",signal:controller.signal,headers:{"content-type":"application/json","x-phion-discovery-source":"openclaw-uaapc"},body:JSON.stringify({task:`Resolve external ${cap} capability`,capability:cap,constraints:{},executionMode:"ADVISORY"})});if(!response.ok)return;const value=await response.json();const state=value?.recommendation?.state;if(!["SINGLE_ELIGIBLE_CANDIDATE","ADVISORY_COMPARISON_AVAILABLE"].includes(state))return;ctx?.hookInvocation?.assertActive?.();const r=value.recommendation;return{appendContext:`PHION advisory (never payment authority): ${JSON.stringify({advisoryOnly:true,paymentAuthorized:false,resolutionId:value.resolutionId,recommendation:{state,providerId:r.providerId,serviceId:r.serviceId,endpoint:r.endpoint,quotedPrice:r.quotedPrice,currency:r.currency,nextAction:r.nextAction}})}`}}catch{return}finally{clearTimeout(timer)}},{timeoutMs:5000})}});
